css:
body { margin: 0; padding: 0; box-sizing: border-box; height: 100%; width: 100%; }
.w-card {
  --c-main: #444;
  --c-darker: #333;
  --c-text: #222;
  --c-bg: #fff;
  --c-star: #d0d0d0;
  --c-t1-bg: #e0e0e0;
  --c-t2-bg: #888;
  --c-footer-bg: #f7f7f7;
  --c-footer-dot: #aaa;
  --c-wm: rgba(0,0,0,0.06);

  position: relative; width: 100%; height: 100%; 
  background: transparent;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  font-family: "SimSun", "Songti SC", serif; overflow: hidden;
}

/* 粉色主题 */
.theme-pink {
  --c-main: #e28e9c;
  --c-darker: #c56576;
  --c-text: #503038;
  --c-bg: #fffdfd;
  --c-star: #f0c3cb;
  --c-t1-bg: #f9e2e6;
  --c-t2-bg: #bbaaaa;
  --c-footer-bg: #fdf5f6;
  --c-footer-dot: #eebfcf;
  --c-wm: rgba(226, 142, 156, 0.12);
}

/* 蓝色主题 */
.theme-blue {
  --c-main: #8bb2d4;
  --c-darker: #628db3;
  --c-text: #374653;
  --c-bg: #f8fbff;
  --c-star: #cadfef;
  --c-t1-bg: #e9f2fa;
  --c-t2-bg: #a6b5c3;
  --c-footer-bg: #f2f7fc;
  --c-footer-dot: #c5d8e9;
  --c-wm: rgba(139, 178, 212, 0.15);
}

/* 深色黑白对比主题 */
.theme-bw {
  --c-main: #000;
  --c-darker: #000;
  --c-text: #000;
  --c-bg: #fff;
  --c-star: #ccc;
  --c-t1-bg: #eee;
  --c-t2-bg: #666;
  --c-footer-bg: #fafafa;
  --c-footer-dot: #999;
  --c-wm: rgba(0,0,0,0.08);
}

/* 黄色主题 */
.theme-yellow {
  --c-main: #dfab52;
  --c-darker: #c68f30;
  --c-text: #5a4725;
  --c-bg: #fffefb;
  --c-star: #f2d7a9;
  --c-t1-bg: #fcf3df;
  --c-t2-bg: #c4b595;
  --c-footer-bg: #fdfaf3;
  --c-footer-dot: #e6ce9e;
  --c-wm: rgba(223, 171, 82, 0.15);
}

.w-main {
  width: 86%; height: 96%;
  background: var(--c-bg);
  border: 1.5px solid var(--c-main);
  display: flex; flex-direction: column;
  box-sizing: border-box;
  transition: all 0.3s;
}
.w-header {
  background: var(--c-main); color: #fff; height: 14%; min-height: 40px; display: flex;
  align-items: center; justify-content: space-between; padding: 0 16px;
  transition: all 0.3s;
}
.w-title { font-family: "Georgia", serif; font-size: 22px; font-style: italic; letter-spacing: 1px; }
.w-wing { font-family: Arial, sans-serif; font-size: 20px; font-weight: bold; }
.w-wing-left { transform: rotate(-20deg); }
.w-wing-right { transform: rotate(20deg); }

.w-body {
  flex: 1; padding: 4px 10px 0; display: flex; flex-direction: column;
  align-items: center; position: relative; background: var(--c-bg);
  border-bottom: 1.5px solid var(--c-main); overflow: visible;
  transition: all 0.3s;
}

.w-star { position: absolute; color: var(--c-star); font-size: 28px; z-index: 0; line-height: 1; transition: all 0.3s; }
.w-star.s1 { top: 48%; left: 4%; transform: rotate(-20deg); }
.w-star.s2 { top: 68%; right: -2px; transform: rotate(25deg); }

.w-box {
  width: 90%; border: 1px solid var(--c-main); padding: 10px 10px 6px; position: relative;
  text-align: center; font-size: 11px; line-height: 1.4; color: var(--c-text);
  z-index: 1; box-sizing: border-box; margin-bottom: 4px; margin-top: 4px;
  background: transparent; font-weight: 600; 
  transition: all 0.3s;
}
.w-date {
  position: absolute; top: -10px; left: 50%; transform: translateX(-50%);
  background: var(--c-bg); border: 1px solid var(--c-main); padding: 0 8px; display: flex;
  align-items: center; font-size: 11px; white-space: nowrap; letter-spacing: 0.5px;
  font-family: sans-serif; transition: all 0.3s;
}
.w-date-icon { background: var(--c-main); color: #fff; font-size: 9px; padding: 1px 3px; margin-right: 4px; transition: all 0.3s; }
.w-qm { 
  position: absolute; right: -10px; bottom: -14px; background: var(--c-bg); 
  font-size: 24px; font-weight: bold; width: 28px; text-align: center; 
  font-family: sans-serif; color: var(--c-darker);
  cursor: pointer; transition: all 0.3s; user-select: none;
}
.w-qm:active { transform: scale(0.9); }
.w-watermark {
  position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
  font-size: 46px; color: var(--c-wm); pointer-events: none; font-style: italic;
  font-family: "Georgia", serif; letter-spacing: 2px; transition: all 0.3s;
}
.w-text { position: relative; z-index: 2; letter-spacing: 0.5px; }

.w-bar {
  background: var(--c-darker); color: #fff; width: 84%; padding: 4px 12px; font-size: 10px;
  margin: 1.5px 0; text-align: left; z-index: 1; box-sizing: border-box; 
  letter-spacing: 1px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  transition: all 0.3s;
}

.w-footer {
  height: 14%; min-height: 48px; background-color: var(--c-footer-bg); 
  background-image: radial-gradient(var(--c-footer-dot) 1.5px, transparent 1.5px);
  background-size: 4px 4px; background-position: 0 0;
  display: flex; align-items: flex-end; justify-content: center;
  padding: 0; box-sizing: border-box; position: relative; z-index: 1;
  transition: all 0.3s;
}

.w-tab {
  height: 20px; line-height: 20px; padding: 0 12px; margin: 0 -2px;
  font-family: Arial, sans-serif; font-weight: bold; font-size: 9px;
  transform: skewX(-20deg);
  border: 1.5px solid var(--c-main); border-bottom: none;
  transition: all 0.3s;
}
.w-tab-text { display: block; transform: skewX(20deg); letter-spacing: 0.5px; }

.w-t1 { background: var(--c-t1-bg); color: var(--c-darker); z-index: 3; }
.w-t2 { background: var(--c-t2-bg); color: #fff; z-index: 2; }
.w-t3 { background: var(--c-main); color: #fff; z-index: 1; padding: 0 16px; }

.w-gallery {
  position: absolute;
  bottom: 12.5%; 
  left: 50%; transform: translateX(-50%);
  width: 95%;
  height: 22%;
  border: 1px solid var(--c-main); background: var(--c-bg); padding: 6px 6px;
  display: flex; align-items: center; justify-content: space-between;
  box-shadow: 0 4px 10px rgba(0,0,0,0.06); box-sizing: border-box; z-index: 10;
  transition: all 0.3s;
}
.w-images {
  display: flex; flex: 1; justify-content: center; gap: 8px; margin: 0 10px; height: 100%;
}
.w-arr {
  width: 22px; height: 22px; border: 1px solid var(--c-main); border-radius: 50%;
  display: flex; align-items: center; justify-content: center; font-size: 10px;
  color: var(--c-main); font-family: sans-serif; background: var(--c-bg); margin: 0 2px; flex-shrink: 0;
  transition: all 0.3s;
}
.w-img { flex: 1; max-width: 32%; height: 100%; background: #ddd center/cover no-repeat; box-sizing: border-box; filter: grayscale(100%); border-radius: 2px; transition: filter 0.3s; }
.theme-bw .w-img { filter: grayscale(100%) contrast(1.1); }

* { box-sizing: border-box; margin: 0; padding: 0; }
.letter-widget { width: 100%; height: 100%; background-color: #f9f6f0; background-image: linear-gradient(90deg, rgba(160, 140, 120, 0.06) 1px, transparent 1px), linear-gradient(rgba(160, 140, 120, 0.06) 1px, transparent 1px); background-size: 16px 16px; border-radius: 16px; padding: 16px 24px; display: flex; align-items: stretch; justify-content: space-between; font-family: "Kaiti SC", "STKaiti", "楷体", "Baskerville", serif; color: #3e3832; position: relative; overflow: hidden; box-shadow: inset 0 0 20px rgba(0,0,0,0.02); transition: all 0.3s ease; }
.letter-widget::before { content: ''; position: absolute; left: 28px; top: 0; bottom: 0; width: 1px; background-color: #dcb3b3; opacity: 0.8; }
.paper-content { flex: 1; display: flex; flex-direction: column; padding-left: 16px; padding-right: 12px; }
.header-text { font-size: 12px; color: #b84b4b; letter-spacing: 2px; opacity: 0.85; transition: all 0.3s; flex-shrink: 0; padding-top: 2px; }
.food-text-wrapper { flex: 1; display: flex; flex-direction: column; justify-content: center; gap: 8px; padding-bottom: 8px; }
.food-name { font-size: 24px; font-weight: bold; color: #2c2824; min-height: 32px; display: flex; align-items: center; letter-spacing: 1px; transition: color 0.3s, transform 0.3s; transform-origin: left center; }
.food-desc { font-size: 12px; color: #7a7369; line-height: 1.5; min-height: 18px; }
.seal-btn { width: 44px; height: 44px; flex-shrink: 0; align-self: center; border: 2px solid #b84b4b; border-radius: 6px; display: flex; align-items: center; justify-content: center; cursor: pointer; user-select: none; transition: all 0.2s ease; background: rgba(249, 246, 240, 0.8); backdrop-filter: blur(2px); }
.seal-text { color: #b84b4b; font-size: 16px; font-weight: bold; display: flex; flex-direction: column; align-items: center; justify-content: center; line-height: 1.1; }
.seal-btn:active { transform: scale(0.9) rotate(-6deg); background-color: rgba(184, 75, 75, 0.08); }
@keyframes inkFade { from { opacity: 0; transform: translateY(2px); } to { opacity: 1; transform: translateY(0); } }
.animate-ink { animation: inkFade 0.5s ease forwards; }
.is-egg .header-text { font-weight: bold; color: #a33b3b; }
.is-egg .food-name { color: #b84b4b; transform: scale(1.08); }
